from pwn import remote
from sage.all import *
import re

def parse_point(s):
    # Extract values from string like (x, y)
    nums = re.findall(r"[-]?[0-9]+", s)
    return tuple(map(int, nums))

def main():
    HOST, PORT = 'crypto.chal.csaw.io', 5000
    r = remote(HOST, PORT)

    # Read until curve params are given
    p = a = b = None
    P1 = P2 = None
    while True:
        line = r.recvline().decode()
        # print(line.strip())  # DEBUG
        if line.startswith('p ='):            p = int(line.split('=')[1].strip())
        elif line.startswith('a ='):          a = int(line.split('=')[1].strip())
        elif line.startswith('b ='):          b = int(line.split('=')[1].strip())
        elif line.startswith('P1 ='):         P1 = parse_point(line.split('=')[1])
        elif line.startswith('P2 ='):         P2 = parse_point(line.split('=')[1])
        elif 'Enter' in line or 'secret' in line.lower():
            break

    # Smart's attack: For anomalous curves (order = p), we can recover k such that Q = kP
    F = FiniteField(p)
    E = EllipticCurve(F, [a, b])
    P = E(P1)
    Q = E(P2)

    # Implement Smart's attack (See: SE link: https://crypto.stackexchange.com/questions/7246/ )
    # Compute R = Q, repeatedly subtract P, keep count until get 0
    # Faster: Use Smart's attack involving lifting, but for small p, can brute force
    # Trying brute force first
    # If very large p, then use Smart's attack
    if p < 2**20:
        # Brute force search! (educationally)
        for k in range(1, p+1):
            if k*P == Q:
                secret = k
                break
    else:
        # Use Smart's attack: use the canonical lifting to Z/p^2 Z and solve
        # E_lift: curve over Zmod(p^2)
        ZZp2 = Zmod(p**2)
        E2 = EllipticCurve(ZZp2, [ZZp2(a), ZZp2(b)])
        Plift = E2(P.xy())
        Qlift = E2(Q.xy())
        # Compute t = (Qlift - k*Plift)/(p*Plift), see Smart's paper
        # The discrete log modulo p^2 is congruent to k mod p
        k_mod_p = discrete_log(Q, P, operation='+')
        secret = k_mod_p

    # Send secret
    r.sendline(str(secret).encode())
    # Print all remaining lines (should include flag)
    try:
        while True:
            l = r.recvline(timeout=2)
            if not l:
                break
            print(l.decode().strip())
    except Exception:
        pass

if __name__ == '__main__':
    main()

