    HOST, PORT = 'crypto.chal.csaw.io', 5000
    r = remote(HOST, PORT)
    p = a = b = None
    P1 = P2 = None
    # Collect everything until prompt for secret
    while True:
        line = r.recvline(timeout=7).decode(errors='replace').strip()
        if line.startswith('p ='):
            p = int(line.split('=',1)[1].strip())
        elif line.startswith('a ='):
            a = int(line.split('=',1)[1].strip())
        elif line.startswith('b ='):
            b = int(line.split('=',1)[1].strip())
        elif line.startswith('P1 =') and '(' in line:
            P1 = parse_point(line.split('=',1)[1].strip())
        elif line.startswith('P2 =') and '(' in line:
            P2 = parse_point(line.split('=',1)[1].strip())
        elif ('secret' in line or 'answer' in line or '?' in line) and all([p, a is not None, b is not None, P1, P2]):
            break
        if line == '':
            break  # avoid infinite loop
    if not all([p, a is not None, b is not None, P1, P2]):
        raise Exception('Missing parameter, got p={}, a={}, b={}, P1={}, P2={}'.format(p,a,b,P1,P2))
    F = GF(p)
    E = EllipticCurve(F, [a, b])
    Px, Py = P1
    Qx, Qy = P2
    P = E(Px, Py)
    Q = E(Qx, Qy)
    try:
        secret = discrete_log(Q, P, operation='+')
    except Exception:
        secret = next(k for k in range(1, p) if k*P == Q)
    r.sendline(str(secret).encode())
    # Read all output including flag
    out = ''
    try:
        while True:
            l = r.recvline(timeout=3)
            if not l:
                break
            l = l.decode(errors='replace').strip()
            print(l)
            out += l + '\n'
    except Exception:
        pass
