from pwn import *
import re

HOST = 'crypto.chal.csaw.io'
PORT = 5000

conn = remote(HOST, PORT)
data = b''
try:
    while True:
        chunk = conn.recv(timeout=2)
        if not chunk:
            break
        data += chunk
except EOFError:
    pass

data = data.decode(errors='ignore')
print('=== RAW DATA ===')
print(data)
print('=== END RAW DATA ===')

# Try to regex out p, a, b, x1, y1, x2, y2
values = {}
for name in ['p', 'a', 'b', 'x1', 'y1', 'x2', 'y2']:
    m = re.search(rf'{name}\s*=\s*(-?\d+)', data)
    if m:
        values[name] = int(m.group(1))
    else:
        print(f"Did not find: {name}")
if len(values)==7:
    print(f"Extracted values: {values}")
conn.close()
